            "source": source,
            "request_id": request_id,
            "mode": mode,
            "expires_at": rec["expires_at"],
            "anchor": {"height": anchor["height"], "block_hash": anchor["block_hash"]},
            "blocks": blocks_tail_raw,
            "tip": recomputed_tip,
